  1130                          if ((language[ix] = tolower(voice_select->languages[ix])) == '-')
  1131                                  n_parts++;
  1132                  }
  1133          }
  1134
  1135          if ((n_parts == 1) && (control & 1)) {
  1136                  if (strcmp(language, "mbrola") == 0) {
  1137                          language[2] = 0; // truncate to "mb"
  1138                          lang_len = 2;
  1139                  }
  1140
  1141                  sprintf(buf, "%s/voices/%s", path_home, language);
  1142                  if (GetFileLength(buf) == -EISDIR) {
  1143                          // A subdirectory name has been specified.  List all the voices in that subdirectory
  1144                          language[lang_len++] = PATHSEP;
  1145                          language[lang_len] = 0;
  1146                          n_parts = -1;
  1147                  }
  1148          }
  1149
  1150          // select those voices which match the specified language
  1151          nv = 0;
  1152          for (ix = 0; ix < n_voices_list; ix++) {
  1153                  vp = voices_list[ix];
  1154
  1155                  if (((control & 1) == 0) && (memcmp(vp->identifier, "mb/", 3) == 0))
  1156                          continue;
  1157
  1158                  if (voice_select->languages == NULL || memcmp(voice_select->languages,"all", 3) == 0) {
  1159                          voices[nv++] = vp;
  1160                          continue;
  1161                  }
  1162
  1163                  if ((score = ScoreVoice(voice_select, language, n_parts, lang_len, voices_list[ix])) > 0) {
  1164                          voices[nv++] = vp;
  1165                          vp->score = score;
  1166                  }
  1167          }
  1168          voices[nv] = NULL; // list terminator
  1169
  1170          if (nv == 0)
  1260          if ((voice_select2.languages == NULL) || (voice_select2.languages[0] == 0)) {
  1261                  // no language is specified. Get language from the named voice
