  1272                  vp = SelectVoiceByName(voices_list, buf);
  1273                  if (vp != NULL) {
  1274                          voice_select2.languages = &(vp->languages[1]);
  1275
  1276                          if ((voice_select2.gender == ENGENDER_UNKNOWN) && (voice_select2.age == 0) && (voice_select2.variant == 0)) {
  1277                                  if (variant_name[0] != 0) {
