  1280                                  }
  1281
  1282                                  return vp->identifier;
  1283                          }
  1284                  }
  1285          }
  1286
  1287          // select and sort voices for the required language
  1288          nv = SetVoiceScores(&voice_select2, voices, 0);
  1289
  1290          if (nv == 0) {
  1291                  // no matching voice, choose the default
