  1294                          nv = 1;
  1295          }
  1296
  1297          gender = 0;
  1298          if ((voice_select2.gender == ENGENDER_FEMALE) || ((voice_select2.age > 0) && (voice_select2.age < 13)))
  1299                  gender = ENGENDER_FEMALE;
  1300          else if (voice_select2.gender == ENGENDER_MALE)
  1301                  gender = ENGENDER_MALE;
  1302
  1303          #define AGE_OLD 60
  1304          if (voice_select2.age < AGE_OLD)
  1305                  aged = 0;
  1306
  1307          p = p_start = variant_lists[gender];
  1308          if (aged == 0)
