  1328                                  p = p_start;
  1329                                  continue;
  1330                          }
  1331
  1332                          vp2 = &voice_variants[n_variants++]; // allocate space for voice variant
  1333                          memcpy(vp2, vp, sizeof(espeak_VOICE)); // copy from the original voice
  1334                          vp2->variant = variant_number;
  1335                          voices2[ix2++] = vp2;
  1336                          p++;
  1337                          j++;
  1338                  }
  1339          }
  1340          // add any more variants to the end of the list
  1341          while ((vp != NULL) && ((variant_number = *p++) != 0) && (n_variants < N_VOICE_VARIANTS)) {
  1342                  vp2 = &voice_variants[n_variants++]; // allocate space for voice variant
  1343                  memcpy(vp2, vp, sizeof(espeak_VOICE)); // copy from the original voice
  1344                  vp2->variant = variant_number;
  1345                  voices2[ix2++] = vp2;
  1346          }
  1347
  1348          // index the sorted list by the required variant number
  1349          if (ix2 == 0)
  1350                  return NULL;
  1351          vp = voices2[voice_select2.variant % ix2];
  1352
  1353          if (vp->variant != 0) {
  1354                  variant_name = ExtractVoiceVariantName(NULL, vp->variant, 0);
  1355                  sprintf(voice_id, "%s+%s", vp->identifier, variant_name);
  1356                  return voice_id;
  1357          }
  1358
  1359          return vp->identifier;
